#!/usr/bin/env python3
import subprocess, sys, os, re, json, collections

REPO = '/home/user/fortress'
def git(*args, binary=False):
    out = subprocess.run(['git', '-C', REPO] + list(args), stdout=subprocess.PIPE, check=True).stdout
    return out if binary else out.decode('utf-8', 'replace')

COORD = {'explorations/coordinator/FACTS.md', 'explorations/coordinator/POSITIONS.md',
         'explorations/coordinator/PLAN.md', 'explorations/coordinator/INDEX.md',
         'explorations/fortress-gap-ledger.md', 'explorations/microgpt-run-c-handover.md'}
TESTDIRS = {'tests', 'compiler_tests', 'library_tests', 'not_passing_yet', 'static_tests', 'compiler_regressions',
            'not_working_compiler_tests', 'not_working_library_tests', 'not_working_static_tests', 'other_compiler_tests',
            'parser_tests', 'linker_tests', 'syntax_abstraction_tests', 'shelltests', 'test_library', 'long_term_not_working',
            'obsolete_interpreter_tests', 'demos'}
CAPT = {'.txt', '.tsv', '.out', '.log', '.csv', '.json'}
PROBE = {'.fss', '.fsi', '.test'}
SCRIPT = {'.sh', '.py', '.js', '.java', '.scala', '.pl', '.rb', '.awk', '.patch', '.diff'}

def category(p):
    ext = os.path.splitext(p)[1].lower()
    if p in COORD: return 'COORD'
    if p.startswith('explorations/'):
        if ext == '.md': return 'REC_REPORTS'
        if ext in CAPT: return 'REC_CAPTURES'
        if ext in PROBE: return 'REC_PROBES'
        if ext in ('.sh', '.py', '.js', '.java', '.scala', '.pl', '.rb', '.awk'): return 'REC_SCRIPTS'
        return 'REC_OTHER'
    if p.startswith('Library/') or p.startswith('ProjectFortress/LibraryBuiltin/'): return 'CODE_LIB'
    if p.startswith('ProjectFortress/src/') and p.endswith('.java'): return 'CODE_JAVA'
    if p.startswith('ProjectFortress/src/') and p.endswith('.scala'): return 'CODE_SCALA'
    if p.startswith('ProjectFortress/astgen/'): return 'CODE_ASTGEN'
    if os.path.basename(p) in ('build.xml',) or p.endswith('.properties'): return 'CODE_BUILD'
    if p == 'Specification/fortress.pdf' or (p.startswith('Specification') and p.endswith('.pdf')): return 'SPEC_PDF'
    if p.startswith('Specification/') and p.endswith('.tex'): return 'SPEC_TEX'
    parts = p.split('/')
    if parts[0] == 'ProjectFortress' and len(parts) > 2 and parts[1] in TESTDIRS: return 'TESTS'
    return 'OTHER_' + parts[0]

def commit_changes(c):
    """return list of (status, old, new, add, dele) for commit c"""
    ns = git('show', '--numstat', '-M', '-z', '--format=', c)
    st = git('show', '--name-status', '-M', '-z', '--format=', c)
    # parse numstat -z
    toks = ns.split('\0')
    nums = []
    i = 0
    while i < len(toks):
        t = toks[i].strip('\n')
        if not t: i += 1; continue
        f = t.split('\t')
        a, d = f[0], f[1]
        if len(f) >= 3 and f[2] != '':
            nums.append((a, d, None, f[2])); i += 1
        else:
            nums.append((a, d, toks[i+1], toks[i+2])); i += 3
    toks = st.split('\0')
    stats = []
    i = 0
    while i < len(toks):
        t = toks[i].strip('\n')
        if not t: i += 1; continue
        if t[0] in 'RC':
            stats.append((t, toks[i+1], toks[i+2])); i += 3
        else:
            stats.append((t, None, toks[i+1])); i += 2
    stmap = {}
    for s, o, n in stats:
        stmap[(o, n)] = s
    res = []
    for a, d, o, n in nums:
        s = stmap.get((o, n))
        if s is None:
            # numstat for R without old
            s = '?'
        res.append((s, o, n, None if a == '-' else int(a), None if d == '-' else int(d)))
    return res

def blob_size(rev, p):
    try:
        return int(git('cat-file', '-s', f'{rev}:{p}').strip())
    except subprocess.CalledProcessError:
        return None

def blob_lines(rev, p):
    try:
        b = git('cat-file', 'blob', f'{rev}:{p}', binary=True)
        return b.count(b'\n')
    except subprocess.CalledProcessError:
        return None

def exists(rev, p):
    r = subprocess.run(['git', '-C', REPO, 'cat-file', '-e', f'{rev}:{p}'], stderr=subprocess.DEVNULL)
    return r.returncode == 0

def main():
    name = sys.argv[1]; base = sys.argv[2]; commits = sys.argv[3:]
    last = commits[-1]
    percat = collections.defaultdict(lambda: {'add': 0, 'del': 0, 'files': set()})
    perfile = collections.OrderedDict()
    for c in commits:
        for s, o, n, a, d in commit_changes(c):
            p = n
            cat = category(p if not s.startswith('D') else p)
            pc = percat[cat]
            pc['add'] += a or 0; pc['del'] += d or 0; pc['files'].add(p)
            e = perfile.setdefault(p, {'events': [], 'add': 0, 'del': 0, 'cat': cat, 'bin': False})
            e['events'].append((c, s, o)); e['add'] += a or 0; e['del'] += d or 0
            if a is None: e['bin'] = True
    out = {'name': name, 'base': base, 'commits': commits, 'cats': {}, 'files': {}}
    for cat, pc in sorted(percat.items()):
        out['cats'][cat] = {'files': len(pc['files']), 'add': pc['add'], 'del': pc['del']}
    for p, e in perfile.items():
        existed_base = exists(base, p)
        first = e['events'][0]
        renamed_from = [ev[2] for ev in e['events'] if ev[1].startswith('R')]
        new = (not existed_base) and not (renamed_from and exists(base, renamed_from[0]))
        at_last = exists(last, p)
        at_head = exists('HEAD', p)
        size = blob_size(last, p) if at_last else None
        lines = blob_lines(last, p) if at_last else None
        out['files'][p] = {'cat': e['cat'], 'add': e['add'], 'del': e['del'], 'bin': e['bin'],
                           'events': [(ev[0][:9], ev[1], ev[2]) for ev in e['events']],
                           'new': new, 'existed_base': existed_base, 'renamed_from': renamed_from,
                           'at_last': at_last, 'at_head': at_head, 'size': size, 'lines': lines}
    json.dump(out, open(f'/tmp/claude-0/-home-user-fortress/fe616d40-a9c6-56d7-9da1-7168a172765d/scratchpad/characterize/batches-3-3.5/{name}.json', 'w'), indent=1)
    for cat, v in out['cats'].items():
        print(cat, v)

main()

