#!/usr/bin/env python3
import subprocess, sys, os, re, json, collections
REPO = '/home/user/fortress'
D = '/tmp/claude-0/-home-user-fortress/fe616d40-a9c6-56d7-9da1-7168a172765d/scratchpad/characterize/batches-3-3.5'
def git(*args, binary=False):
    out = subprocess.run(['git', '-C', REPO] + list(args), stdout=subprocess.PIPE, check=True).stdout
    return out if binary else out.decode('utf-8', 'replace')

# load all tracked md at HEAD
mdpaths = [p for p in git('ls-files', '-z', '--', '*.md').split('\0') if p]
mdtext = {}
for p in mdpaths:
    try:
        mdtext[p] = open(os.path.join(REPO, p), encoding='utf-8', errors='replace').read()
    except Exception:
        mdtext[p] = ''
allfiles = [p for p in git('ls-files', '-z').split('\0') if p]
bcount = collections.Counter(os.path.basename(p) for p in allfiles)
COMMON = {'README.md', 'REPORT.md', 'record.md', 'RECORD.md', 'SKEPTIC.md', 'JUDGE.md', 'JUDGE-review.md', 'REPAIR-review.md'}

def hits(s, self_path):
    return [p for p, t in mdtext.items() if p != self_path and s in t]

def cited(p, bcount_extra):
    b = os.path.basename(p)
    d = os.path.dirname(p)
    if b in COMMON:
        # cited through directory: directory path (from compile-ladder/ or explorations/) in an md outside that dir
        key = d.split('explorations/', 1)[-1]
        short = '/'.join(d.split('/')[-2:])
        h = [q for q in mdtext if not q.startswith(d + '/') and (key in mdtext[q] or short in mdtext[q])]
        return ('dir', bool(h), bool(h))
    uniq = (bcount.get(b, 0) + bcount_extra.get(b, 0)) <= 1
    hb = hits(b, p)
    basename_cited = bool(hb)
    # strict: full path, or a >=2-component suffix, or unique basename
    parts = p.split('/')
    strict = False
    if uniq:
        strict = basename_cited
    else:
        for k in range(2, len(parts) + 1):
            suf = '/'.join(parts[-k:])
            if any(suf in mdtext[q] for q in hb):
                strict = True; break
    # cited through a directory (parent dirs, >=2 components, followed by '/')
    dircited = False
    for k in range(len(parts) - 1, 2, -1):
        dd = '/'.join(parts[:k])
        short = '/'.join(parts[k-2:k]) + '/'
        if any(short in t for q, t in mdtext.items() if q != p):
            dircited = True; break
    return ('uniq' if uniq else 'dup', basename_cited, strict or False, dircited)

def main(name):
    d = json.load(open(f'{D}/{name}.json'))
    files = d['files']
    # basenames of files not at HEAD also count for uniqueness
    extra = collections.Counter(os.path.basename(p) for p, f in files.items() if not f['at_head'])
    res = {'name': name, 'cats': d['cats']}
    # per record category
    rec = {}
    for cat in ['REC_REPORTS', 'REC_CAPTURES', 'REC_PROBES', 'REC_SCRIPTS', 'REC_OTHER']:
        fs = {p: f for p, f in files.items() if f['cat'] == cat}
        new = {p: f for p, f in fs.items() if f['new']}
        mod = {p: f for p, f in fs.items() if not f['new']}
        rec[cat] = {
            'files_touched': len(fs), 'new': len(new), 'modified_existing': len(mod),
            'add': sum(f['add'] for f in fs.values()), 'del': sum(f['del'] for f in fs.values()),
            'new_lines_at_landing': sum((f['lines'] or 0) for f in new.values() if f['at_last']),
            'new_bytes_at_landing': sum((f['size'] or 0) for f in new.values() if f['at_last']),
            'new_deleted_in_batch': sum(1 for f in new.values() if not f['at_last']),
            'new_gone_at_head': sum(1 for f in new.values() if f['at_last'] and not f['at_head']),
        }
    res['records'] = rec
    allrec = {p: f for p, f in files.items() if f['cat'].startswith('REC_')}
    newrec = {p: f for p, f in allrec.items() if f['new'] and f['at_last']}
    res['records_total'] = {'files': len(allrec), 'new': len(newrec), 'add': sum(f['add'] for f in allrec.values()),
                            'del': sum(f['del'] for f in allrec.values()),
                            'bytes_new': sum(f['size'] or 0 for f in newrec.values())}
    # largest new record files
    big = sorted(newrec.items(), key=lambda kv: -(kv[1]['lines'] or 0))[:8]
    res['largest'] = [(p, f['lines'], f['size']) for p, f in big]
    bigb = sorted(newrec.items(), key=lambda kv: -(kv[1]['size'] or 0))[:5]
    res['largest_bytes'] = [(p, f['lines'], f['size']) for p, f in bigb]
    # cited
    c = collections.Counter(); cl = collections.Counter()
    uncited_list = []
    percat_c = collections.defaultdict(lambda: collections.Counter())
    for p, f in newrec.items():
        r = cited(p, extra)
        if r[0] == 'dir':
            key_b = 'cited' if r[1] else 'uncited'; key_s = key_b; key_d = key_b
        else:
            key_b = 'cited' if r[1] else 'uncited'
            key_s = 'cited' if r[2] else 'uncited'
            key_d = 'cited' if (r[2] or r[3]) else 'uncited'
        L = f['lines'] or 0
        c['basename_' + key_b] += 1; cl['basename_' + key_b] += L
        c['strict_' + key_s] += 1; cl['strict_' + key_s] += L
        c['strictdir_' + key_d] += 1; cl['strictdir_' + key_d] += L
        percat_c[f['cat']]['basename_' + key_b] += 1
        percat_c[f['cat']]['strict_' + key_s] += 1
        if key_b == 'uncited': uncited_list.append((p, L))
        if r[0] == 'dup': c['dup_basename'] += 1
    res['cited_files'] = dict(c); res['cited_lines'] = dict(cl)
    res['cited_percat'] = {k: dict(v) for k, v in percat_c.items()}
    # uncited by directory
    ud = collections.Counter(); udl = collections.Counter()
    for p, L in uncited_list:
        k = '/'.join(p.split('/')[:4]); ud[k] += 1; udl[k] += L
    res['uncited_by_dir'] = [(k, ud[k], udl[k]) for k in sorted(ud, key=lambda k: -ud[k])]
    # tests
    tests = {p: f for p, f in files.items() if f['cat'] == 'TESTS'}
    t = collections.Counter(); tl = collections.Counter()
    tlist = collections.defaultdict(list)
    for p, f in tests.items():
        b = os.path.basename(p)
        if f['renamed_from'] and os.path.basename(f['renamed_from'][0]).startswith('XXX') and not b.startswith('XXX'):
            k = 'promoted'
        elif f['new'] and not f['at_last']:
            k = 'new_then_deleted'
        elif f['new']:
            k = 'new_xxx' if b.startswith('XXX') else 'new_plain'
        elif not f['at_last']:
            k = 'deleted'
        else:
            k = 'modified'
        t[k] += 1; tl[k + '_add'] += f['add']; tl[k + '_del'] += f['del']
        tlist[k].append((p, f['lines'], f['add'], f['del']))
    res['tests'] = {'counts': dict(t), 'lines': dict(tl), 'add': sum(f['add'] for f in tests.values()),
                    'del': sum(f['del'] for f in tests.values()),
                    'rung_suffixed': sorted(p for p in tests if re.search(r'Rung[A-Z0-9]|Batch', os.path.basename(p))),
                    'rung_suffixed_new': sum(1 for p, f in tests.items() if f['new'] and re.search(r'Rung[A-Z0-9]|Batch', os.path.basename(p))),
                    'list': {k: v for k, v in tlist.items()}}
    newt = [(p, f['lines']) for p, f in tests.items() if f['new'] and f['at_last']]
    res['tests']['largest_new'] = sorted(newt, key=lambda x: -(x[1] or 0))[:3]
    # code
    res['code'] = {p: (f['add'], f['del'], f['new']) for p, f in files.items() if f['cat'].startswith('CODE') or f['cat'].startswith('SPEC')}
    res['coord'] = {p: (f['add'], f['del']) for p, f in files.items() if f['cat'] == 'COORD'}
    res['other'] = {p: (f['add'], f['del']) for p, f in files.items() if f['cat'].startswith('OTHER')}
    # oddities: new then deleted in batch, gone at head
    res['deleted_in_batch'] = [p for p, f in files.items() if f['new'] and not f['at_last']]
    res['gone_at_head'] = [p for p, f in files.items() if f['at_last'] and not f['at_head']]
    res['gone_at_head_count'] = len(res['gone_at_head'])
    json.dump(res, open(f'{D}/{name}-analysis.json', 'w'), indent=1)

for n in sys.argv[1:]:
